# inspect overlaps
over_pairs = {}
for (y,x) in markers:
    cells = [(y-1+dy, x+dx) for dy in range(3) for dx in range(3) if 0<=y-1+dy<H and 0<=x+dx<W]
    for c in cells:
        if cov[c]>1:
            over_pairs.setdefault(c, []).append((y,x))
cells_sorted = sorted(over_pairs)
# group by marker pairs
print("overlap cells and their markers:")
for c in cells_sorted[:20]:
    print(c, over_pairs[c])
# Which markers overlap each other
import itertools
pairs = set()
for c,l in over_pairs.items():
    for p in itertools.combinations(sorted(l),2): pairs.add(p)
print(len(pairs), 'marker pairs overlap')
for p in sorted(pairs): print(p, 'offset diff', (p[1][0]-p[0][0], p[1][1]-p[0][1]))

# check overlap cell values under each writer
conflicts = []
for c, l in over_pairs.items():
    vals = []
    for (y,x) in l:
        vals.append(stamp[c[0]-(y-1), c[1]-x])
    if len(set(vals))>1:
        conflicts.append((c,l,vals))
print('conflicting overlaps:', len(conflicts))
for cf in conflicts: print(cf)

def conflicts_for(dx0):
    cov2 = {}
    conf = []
    for (y,x) in markers:
        for dy in range(3):
            for dx in range(3):
                yy,xx = y-1+dy, x+dx0+dx
                if 0<=yy<H and 0<=xx<W:
                    v = stamp[dy,dx]
                    if (yy,xx) in cov2 and cov2[yy,xx][0]!=v:
                        conf.append(((yy,xx), cov2[(yy,xx)], (v,(y,x))))
                    cov2[(yy,xx)] = (v,(y,x))
    return conf
for dx0 in (-1,0):
    c = conflicts_for(dx0)
    print('dx0=',dx0,'conflicts:',len(c))
    for x in c[:8]: print('  ',x)

def build(dx0):
    out = np.full((H,W),4)
    for (y,x) in markers:
        for dy in range(3):
            for dx in range(3):
                if stamp[dy,dx]!=4:
                    yy,xx = y-1+dy, x+dx0+dx
                    if 0<=yy<H and 0<=xx<W:
                        out[yy,xx]=stamp[dy,dx]
    return out
o0 = build(0); om1 = build(-1)
print('differ:', (o0!=om1).sum())
nz0 = sorted({(o0[y,x]) for y in range(H) for x in range(W) if o0[y,x]!=4})
print('colors:', nz0)
print(o0.tolist())

for name in ['g','grid','test','tmpl','a','out','vals','mset']:
    v = globals().get(name)
    try:
        import numpy as _np
        arr = _np.array(v)
        print(name, arr.shape, arr.dtype)
    except Exception as e:
