# conflicts under transparent center-anchor
writes = {}  # cell -> list of (marker_idx, value) in row-major marker order
for mi,(y,x) in enumerate(markers):
    for dy in (-1,0,1):
        for dx in (-1,0,1):
            v = stamp[dy+1,dx+1]
            if v != 4:
                writes.setdefault((y+dy,x+dx), []).append((mi,v))
conf = {k:v for k,v in writes.items() if len({vv for _,vv in v})>1}
print('transparent-conflict cells:', conf)

# variant A: opaque full 3x3 (incl background 4), row-major marker order, later wins
oA = np.full((H,W), bg)
for (y,x) in markers:
    oA[y-1:y+2, x-1:x+2] = stamp
# variant B: nonzero-only writes, later wins
oB = np.full((H,W), bg)
for (y,x) in markers:
    for dy in (-1,0,1):
        for dx in (-1,0,1):
            v = stamp[dy+1,dx+1]
            if v!=4: oB[y+dy,x+dx]=v
# variant C: nonzero-only, first wins (== transparent) = current out
print('A vs out diff:', int((oA!=out).sum()))
print('B vs out diff:', int((oB!=out).sum()))
d = np.argwhere(oB!=out)
print('B diff cells:', [(int(y),int(x),int(out[y,x]),int(oB[y,x])) for y,x in d])
